import{_ as a,o,c as t,ag as d}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Painel /nay","description":"","frontmatter":{},"headers":[],"relativePath":"pt/nay-lib/panel.md","filePath":"pt/nay-lib/panel.md"}'),i={name:"pt/nay-lib/panel.md"};function s(r,e,n,c,p,l){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="painel-nay" tabindex="-1">Painel /nay <a class="header-anchor" href="#painel-nay" aria-label="Permalink to &quot;Painel /nay&quot;">​</a></h1><p>Escreva <code>/nay</code> no jogo para abrir o painel de definições. Vê todos os scripts Nayretis que tem permissão para configurar. Os jogadores com <code>nay.admin</code> veem também a secção <strong>Servidor</strong>: a página Nayretis, Permissões, API, Webhooks e Registo.</p><p>As definições são guardadas na base de dados. Quando clica em <strong>Guardar</strong>, o novo valor é verificado, armazenado, gravado no <a href="/pt/nay-lib/audit">registo</a> e aplicado de imediato a todos os jogadores ligados. Não é preciso reiniciar.</p><p>Algumas páginas de scripts têm também botões de ação, como <strong>Gerir túneis</strong> na página Car Wash.</p><h2 id="definicoes-nayretis" tabindex="-1">Definições Nayretis <a class="header-anchor" href="#definicoes-nayretis" aria-label="Permalink to &quot;Definições Nayretis&quot;">​</a></h2><p>A página <strong>Nayretis</strong> reúne as definições partilhadas por todos os scripts.</p><p>A coluna <strong>No /nay</strong> mostra o nome apresentado no painel. A chave é o nome usado pelo <code>config.lua</code> e pela <a href="/pt/nay-lib/api">API HTTP</a>.</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Idioma</td><td><code>Locale</code></td><td>idioma</td><td>inglês, ou o valor de <code>nay:locale</code></td><td>Idioma de todos os scripts Nayretis: inglês, francês, espanhol, português, polaco ou alemão.</td></tr><tr><td>Tema da interface</td><td><code>Theme</code></td><td><code>graphite</code> ou <code>papier</code></td><td><code>graphite</code></td><td>Aspeto das interfaces Nayretis: escuro (Graphite) ou claro (Papier).</td></tr><tr><td>API HTTP</td><td><code>ApiEnabled</code></td><td>ligado / desligado</td><td>desligado</td><td>Ativa a <a href="/pt/nay-lib/api">API HTTP</a>. Enquanto estiver desativada, todas as rotas respondem <code>503 api_disabled</code>.</td></tr><tr><td>Tamanho máximo do pedido (KB)</td><td><code>ApiMaxBodyKb</code></td><td>número, 1 a 10240</td><td>1024</td><td>Maior corpo de pedido aceite pela API, em KB.</td></tr><tr><td>Retenção do registo (dias)</td><td><code>AuditRetentionDays</code></td><td>número, 0 a 3650</td><td>90</td><td>As linhas do registo mais antigas do que isso são apagadas todos os dias. 0 mantém tudo.</td></tr></tbody></table><h2 id="quem-pode-abrir-o-painel" tabindex="-1">Quem pode abrir o painel <a class="header-anchor" href="#quem-pode-abrir-o-painel" aria-label="Permalink to &quot;Quem pode abrir o painel&quot;">​</a></h2><ul><li><code>nay.admin</code> dá acesso a tudo.</li><li><code>nay.config</code> dá acesso às definições de todos os scripts.</li><li><code>nay.audit</code> abre o painel no registo.</li><li><code>&lt;resource&gt;.config</code> dá acesso às definições de um script, por exemplo <code>nay_car_wash.config</code>.</li></ul><p>Consulte <a href="/pt/nay-lib/permissions">Permissões</a> para os conceder.</p>',11)])])}const g=a(i,[["render",s]]);export{h as __pageData,g as default};
